// Loop over input items and add a new field called 'images' to the JSON of each one
for (const item of $input.all()) {
  const md = item.json.document?.md_content ?? '';
  const matches = md.matchAll(/!\[[^\]]*\]\(([^)\s]+)\)/g);
  item.json.images = [...new Set([...matches].map(m => m[1].split('/').pop()))];
}

return $input.all();

// Loop over input items and rewrite image references in md_content to full URLs
const BASE_URL = 'http://localhost:8080';

for (const item of $input.all()) {
  const doc = item.json.document;
  if (!doc || typeof doc.md_content !== 'string') continue;

  doc.md_content = doc.md_content.replace(
    /!\[([^\]]*)\]\(([^)\s]+)\)/g,
    (match, alt, src) => {
      if (/^(https?:)?\/\//i.test(src) || src.startsWith('data:')) return match;
      const fileName = src.split('/').pop();
      return `![${alt}](${BASE_URL}/${encodeURIComponent(fileName)})`;
    }
  );
}

return $input.all();
